async resolvePermissions(identity, grantsService = this.grants) {
    const unrestricted = (await grantsService.unrestricted?.(identity)) === true;
    const grants = await grantsService.resolveAll(identity);
    const grouped = new Map();
    for (const grant of grants) {
        if (grant.policy !== undefined) {
            if (!this.resourceTypes.getAction(grant.resource.type, grant.resource.id, grant.action)?.scope)
                continue;
            const decision = await this.authorizeWithGrants({ ...identity, resource: grant.resource, action: grant.action }, grantsService, this.constraints, false);
            if (decision.effect !== 'permit')
                continue;
        }
        const key = `${grant.resource.type}\u0000${grant.resource.id}`;
        const permission = grouped.get(key) ?? {
            resource: grant.resource,
            actions: new Set(),
        };
        permission.actions.add(grant.action);
        grouped.set(key, permission);
    }
    return {
        unrestricted,
        permissions: [...grouped.values()]
            .sort((left, right) => {
            const leftKey = `${left.resource.type}\u0000${left.resource.id}`;
            const rightKey = `${right.resource.type}\u0000${right.resource.id}`;
            return leftKey.localeCompare(rightKey);
        })
            .map((permission) => ({
            resource: permission.resource,
            actions: [...permission.actions].sort(),
        })),
    };
}

/** Build a portable resource without registering it into an application. */
export function defineAuthorizationResource(name, configure) {
    if (!name)
        throw new TypeError('A resource name is required');
    const result = configure(new AuthorizationResourceBuilder({
        name,
        title: name,
        group: '',
        actions: [],
    }));
    const definition = result.build();
    if (!definition.group || !definition.actions.length)
        throw new TypeError('A resource requires a group and actions');
    return new AuthorizationResourceBuilder(definition);
}

export function buildResourceGrant(definition, actions) {
    if ((Array.isArray(actions) ? actions : Object.keys(actions)).some((action) => !definition.actions.some((item) => item.name === action)))
        throw new TypeError('Unknown business resource or action');
    return structuredClone({
        resource: { type: 'resource', id: definition.name },
        actions: Array.isArray(actions)
            ? actions.map((action) => ({ action }))
            : Object.entries(actions).map(([action, scopes]) => ({
                action,
                policy: { type: 'resource', ...scopes },
            })),
    });
}

expand(grant) {
    if (grant.resource.type !== 'resource')
        return [grant];
    const action = this.definitions
        .get(grant.resource.id)
        ?.actions.find((action) => action.name === grant.action);
    if (!action || (grant.policy && grant.policy.type !== 'resource'))
        throw new TypeError('Invalid business resource grant');
    for (const key of Object.keys(grant.policy ?? {}))
        if (key !== 'type' && !action.scopes?.[key])
            throw new TypeError(`Unknown action scope: ${key}`);
    for (const [key, scope] of Object.entries(action.scopes ?? {})) {
        const selected = grant.policy?.[key] ?? scope.defaultValue;
        const selectedKey = typeof selected === 'string'
            ? selected
            : selected && typeof selected === 'object' && !Array.isArray(selected)
                ? Reflect.get(selected, 'key')
                : undefined;
        if (selected !== undefined &&
            selected !== '' &&
            (typeof selectedKey !== 'string' ||
                (scope.options !== undefined && !scope.options.includes(selectedKey))))
            throw new TypeError('Unknown scope option');
    }
    return [
        grant,
        ...action.grants.flatMap((target) => target.actions.map((operation) => {
            const scopeKey = operation.policy?.scope;
            const selected = typeof scopeKey === 'string'
                ? (grant.policy?.[scopeKey] ??
                    action.scopes?.[scopeKey]?.defaultValue)
                : undefined;
            return {
                ...grant,
                resource: target.resource,
                action: operation.action,
                policy: operation.policy && {
                    ...operation.policy,
                    ...(selected !== undefined && selected !== ''
                        ? { recordAccess: [selected] }
                        : {}),
                },
                origin: {
                    resource: grant.resource,
                    action: grant.action,
                    ...(typeof scopeKey === 'string' ? { scopeKey } : {}),
                },
            };
        })),
    ];
}

async resolveEffectiveScope(principal, resource, action, configs, constraints, requestedFields) {
    // Each grant keeps its own fields and role filters through scope evaluation.
    const branches = await Promise.all(configs.map(async (config) => {
        const positive = await this.compileScopes(principal, resource, action, config.recordAccess ?? []);
        positive.push(...(await this.compileConstraints([...constraints, ...(config.branchConstraints ?? [])].filter((item) => item.effect === 'expand'), principal, resource, action)));
        const branchRestrictions = await this.compileConstraints((config.branchConstraints ?? []).filter((item) => item.effect === 'restrict'), principal, resource, action);
        return {
            config,
            scope: allScopes([anyScope(positive), ...branchRestrictions]),
        };
    }));
    const restrictions = await this.compileConstraints(constraints.filter((item) => item.effect === 'restrict'), principal, resource, action);
    const fields = resolveDatabaseFields(configs, action);
    const requested = {
        ...requestedFields,
        ...(action === 'read'
            ? { output: resolveActionFields(action, fields, resource) }
            : { input: resolveActionFields(action, fields, resource) }),
    };
    const required = [
        anyScope(branches.map((branch) => branch.scope)),
    ];
    for (const direction of [
        'input',
        'output',
        'filter',
        'sort',
        'group',
    ]) {
        for (const field of requested[direction] ?? []) {
            if (branches.every((branch) => databaseFieldsAllowed({ [direction]: [field] }, resolveDatabaseFields([branch.config], action))))
                continue;
            required.push(anyScope(branches
                .filter((branch) => databaseFieldsAllowed({ [direction]: [field] }, resolveDatabaseFields([branch.config], action)))
                .map((branch) => branch.scope)));
        }
    }
    return allScopes([...required, ...restrictions]);
}

async authorize(request, grantsService, constraintsService) {
    const resourceId = request.resource.id;
    const unregistered = this.unregistered(resourceId);
    if (unregistered)
        return unregistered;
    const resolved = await this.collection(resourceId, request.action);
    if ('effect' in resolved)
        return resolved;
    const resource = resolved;
    const params = request.params;
    if (!databaseCollectionFieldsKnown(resource, params?.fields)) {
        return this.deny('UNKNOWN_DATABASE_FIELD', `One or more requested fields are not registered for ${resourceId}`);
    }
    const resolvedGrants = await grantsService.resolve({
        principal: request.principal,
        subjects: request.subjects,
        resource: { type: 'database.collection', id: resourceId },
        action: request.action,
    });
    const grants = params?.operation
        ? resolvedGrants.filter((grant) => grant.origin?.resource.id === params.operation?.resource &&
            grant.origin?.action === params.operation?.action)
        : resolvedGrants;
    const configs = grants.flatMap(toDatabaseGrant);
    if (configs.length === 0) {
        return this.deny('NO_OBJECT_PERMISSION', `No database grant allows ${resourceId}.${request.action}`);
    }
    const fields = resolveDatabaseFields(configs, request.action);
    if (!databaseFieldsAllowed(params?.fields, fields)) {
        return this.deny('FIELD_NOT_ALLOWED', 'One or more input, output, filter, sort, or group fields are not allowed');
    }
    const reasons = grants.map((grant) => ({
        code: 'GRANT_MATCHED',
        message: `${grant.source.plugin}:${grant.source.id} allows ${resourceId}.${request.action}`,
        plugin: 'database',
        details: { source: grant.source },
    }));

async can({ resource, action }) {
    const snapshot = await this.permissions();
    if (snapshot.unrestricted)
        return true;
    return snapshot.permissions.some((permission) => permission.resource.type === resource.type &&
        (permission.resource.id === '*' ||
            permission.resource.id === resource.id) &&
        permission.actions.includes(action));
}

